} Edge;

typedef struct {
    int parent;
    int rank;
} DSU;

int cmp_edges(const void *a, const void *b) {
    long long wa = ((const Edge *)a)->w;
    long long wb = ((const Edge *)b)->w;
    if (wa < wb) return -1;
    if (wa > wb) return 1;
    return 0;
}

int find_set(DSU *dsu, int v) {
    if (dsu[v].parent != v)
        dsu[v].parent = find_set(dsu, dsu[v].parent);
    return dsu[v].parent;
}

int union_sets(DSU *dsu, int a, int b) {
    a = find_set(dsu, a);
    b = find_set(dsu, b);
    if (a == b) return 0;
    if (dsu[a].rank < dsu[b].rank) {
        int tmp = a;
        a = b;
        b = tmp;
    }
    dsu[b].parent = a;
    if (dsu[a].rank == dsu[b].rank)
        dsu[a].rank++;
    return 1;
}

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    Edge *edges = (Edge *)malloc((size_t)m * sizeof(Edge));
    DSU *dsu = (DSU *)malloc((size_t)(n + 1) * sizeof(DSU));

    for (int i = 0; i < m; i++) {
        scanf("%d %d %lld", &edges[i].u, &edges[i].v, &edges[i].w);
    }

    for (int i = 1; i <= n; i++) {
        dsu[i].parent = i;
        dsu[i].rank = 0;
    }

    qsort(edges, m, sizeof(Edge), cmp_edges);

    long long mst_sum = 0;
    int used = 0;

    for (int i = 0; i < m && used < n - 1; i++) {
        if (union_sets(dsu, edges[i].u, edges[i].v)) {
            mst_sum += edges[i].w;
